'use strict';
let agendaStart='2026-09-28',agendaCategory='Todas',agendaDay='Todos';
let selectedSession={...weeklySessions.find(s=>s.category==='2016–2017'&&s.day===2),date:'2026-09-29',key:'2026-09-29_2016–2017-2'};
let sessionRecords={},coachWork={},payStart='2026-09-28',payEnd='2026-10-04',payCoach='Todos';
const niceDate=d=>d.split('-').reverse().join('/');
const coachNames=s=>s.coaches.map(id=>coachById(id).name).join(' · ');
const currentRecord=()=>sessionRecords[selectedSession.key]??={attendance:{},saved:false,plan:'',notes:'',done:false};
const sessionPlayers=()=>players.filter(p=>p.category===selectedSession.category);
const forCoach=s=>role==='admin'||s.coaches.includes(selectedCoach);
const oldRender=render;
render=function(){oldRender();const el=document.querySelector('#coach-picker');if(el)el.remove();if(role==='coach'){const label=document.createElement('label');label.id='coach-picker';label.className='coach-picker';label.innerHTML='Entrenador de prueba <select aria-label="Elegir entrenador" onchange="changeCoach(this.value)">'+CLUB.coaches.map(c=>`<option value="${c.id}" ${c.id===selectedCoach?'selected':''}>${c.name}</option>`).join('')+'</select>';main.prepend(label);}document.querySelector('.user').innerHTML='<span class="avatar">'+(role==='coach'?initials(coachById(selectedCoach).name):'FA')+'</span><div>'+esc(role==='coach'?coachById(selectedCoach).name:'Felipe Abril')+'<small id="role-label">'+(role==='coach'?'Entrenador':'Coordinador · Administración')+'</small></div>';};
function changeCoach(id){if(!coachById(id))return;selectedCoach=id;const s=occurrences(agendaStart,isoAdd(agendaStart,6)).find(s=>s.coaches.includes(id));if(s)selectedSession=s;go('inicio');}
function openSession(key,next='asistencia'){const s=occurrences(agendaStart,isoAdd(agendaStart,6)).find(s=>s.key===key);if(!s||!forCoach(s))return toast('La sesión no está disponible en esta vista.');selectedSession=s;go(next);}
function teamView(){return title('ORGANIZACIÓN DEL CLUB','Las personas detrás del equipo.','7 categorías · 9 entrenadores · 2 canchas')+`<div class="admin-grid">${CLUB.administration.map(a=>`<article class="admin-card"><span class="avatar">${a.name==='Por definir'?'—':initials(a.name)}</span><div><small>${a.role}</small><h3>${a.name}</h3>${a.name==='Felipe Abril'?'<span class="muted">También entrenador</span>':''}${a.name==='Por definir'?'<span class="badge warn">Pendiente de asignación</span>':''}</div></article>`).join('')}</div><section class="card"><div class="card-head"><div><h2>Cuerpo técnico</h2><p>Tarifa por entrenador y por práctica de 90 minutos.</p></div><span class="badge blue">9 entrenadores</span></div><div class="table-wrap"><table><thead><tr><th>Entrenador</th><th>Categorías</th><th>Prácticas / semana</th><th>Por práctica</th><th>Estimado semanal</th></tr></thead><tbody>${CLUB.coaches.map(c=>{const n=weeklySessions.filter(s=>s.coaches.includes(c.id)).length;return `<tr><td><div class="person"><span class="avatar">${initials(c.name)}</span><div><strong>${c.name}</strong>${c.id==='felipe'?'<small>Coordinador y entrenador</small>':''}${c.id==='diego'?'<small>Dos prácticas los lunes, miércoles y viernes</small>':''}</div></div></td><td>${coachCategories(c.id).join('<br>')}</td><td>${n}</td><td>${money(c.rate)}</td><td><b>${money(n*c.rate)}</b></td></tr>`}).join('')}</tbody></table></div></section><section class="card"><div class="card-head"><div><h2>Categorías y horarios</h2><p>La agenda conserva los profesores asignados a cada día.</p></div><button class="btn link" onclick="go('sesiones')">Ver agenda</button></div><div class="category-grid">${CLUB.categories.map(c=>{const ss=weeklySessions.filter(s=>s.category===c).sort((a,b)=>a.day-b.day);return `<article class="category-card"><h3>${c}</h3>${ss.map(s=>`<div class="category-line"><b>${WEEKDAYS[s.day]} · ${s.start}–${s.end}</b><span>${CLUB.venues[s.venue]}</span><small>${coachNames(s)}</small></div>`).join('')}</article>`}).join('')}</div></section>`;}
trainingCard=function(){let s=selectedSession;if(!forCoach(s))s=occurrences(agendaStart,isoAdd(agendaStart,6)).find(forCoach);if(!s)return '';return `<section class="card training"><div class="card-head"><div><h2>Tu próxima lista</h2><p>${WEEKDAYS[s.day]} · ${niceDate(s.date)}</p></div>${icon('ball')}</div><div class="training-inner"><span class="tag">${s.start}–${s.end} · 90 minutos</span><h3>Categoría ${s.category}</h3><p>${CLUB.venues[s.venue]}<br>${coachNames(s)}</p><button class="btn" onclick="openSession('${s.key}')">${icon('check')}Tomar asistencia</button><button class="btn link" style="color:white;margin-top:12px;width:100%" onclick="go('sesiones')">Ver todos los entrenamientos</button></div></section>`;};
coachHome=function(){const ps=players.filter(p=>coachCategories(selectedCoach).includes(p.category));const ss=occurrences(agendaStart,isoAdd(agendaStart,6)).filter(forCoach);return title('MI JORNADA',coachById(selectedCoach).name,'Tus categorías: '+coachCategories(selectedCoach).join(' · '))+`<div class="stats">${stat('Mis deportistas de prueba',ps.length,'Solo las fichas ficticias disponibles','users')}${stat('Mis categorías',coachCategories(selectedCoach).length,'Asignaciones confirmadas','ball')}${stat('Prácticas semanales',ss.length,'Según el horario habitual','calendar')}${stat('Duración por práctica','90 min','Por categoría y sesión','clock')}</div><div class="dashboard-grid"><div>${trainingCard()}</div><div><section class="card"><div class="card-head"><h2>Mi semana</h2></div>${ss.map(s=>`<div class="info-row"><div><strong>${WEEKDAYS[s.day]} · ${s.category}</strong><small>${s.start}–${s.end} · ${CLUB.venues[s.venue]}</small></div><button class="btn link" onclick="openSession('${s.key}')">Abrir</button></div>`).join('')}</section></div></div>`;};
function agendaMove(n){agendaStart=isoAdd(agendaStart,n);render();}
sessionsView=function(){let ss=occurrences(agendaStart,isoAdd(agendaStart,6)).filter(forCoach);const shown=ss.filter(s=>(agendaCategory==='Todas'||s.category===agendaCategory)&&(agendaDay==='Todos'||s.day===Number(agendaDay))).sort((a,b)=>a.date.localeCompare(b.date)||a.start.localeCompare(b.start)||a.category.localeCompare(b.category));return title('AGENDA DE ENTRENAMIENTOS','Cada categoría, en su cancha.',niceDate(agendaStart)+' al '+niceDate(isoAdd(agendaStart,6)),btn('Semana anterior','agendaMove(-7)')+btn('Semana siguiente','agendaMove(7)'))+`<div class="toolbar"><select class="filter" aria-label="Categoría de la agenda" onchange="agendaCategory=this.value;render()"><option>Todas</option>${CLUB.categories.map(c=>`<option ${agendaCategory===c?'selected':''}>${c}</option>`).join('')}</select><select class="filter" aria-label="Día de la agenda" onchange="agendaDay=this.value;render()"><option value="Todos">Todos los días</option>${[1,2,3,4,5].map(d=>`<option value="${d}" ${agendaDay===String(d)?'selected':''}>${WEEKDAYS[d]}</option>`).join('')}</select><span class="badge blue">${shown.length} sesiones</span></div>${shown.map(s=>{const r=sessionRecords[s.key];return `<section class="card"><div class="session-card"><div class="datebox"><span>${WEEKDAYS[s.day].slice(0,3).toUpperCase()}</span><strong>${s.date.slice(-2)}</strong></div><div class="session-content"><div class="view-topline"><h3>Categoría ${s.category}</h3><span class="badge ${r?.done?'ok':'blue'}">${r?.done?'Realizada · prueba':'Programada'}</span></div><p><b>${s.start}–${s.end}</b> · ${CLUB.venues[s.venue]}</p><p>${coachNames(s)}</p></div><div class="session-actions"><button class="btn" onclick="openSession('${s.key}','planeacion')">Planeación</button><button class="btn primary" onclick="openSession('${s.key}')">Tomar lista</button></div></div></section>`}).join('')||'<div class="empty">No hay sesiones con estos filtros.</div>'}`;};
// Keep the new session detail inside the same navigation section.
const renderWithCoach=render;
render=function(){if(view==='planeacion'){const previous=view;view='sesiones';renderWithCoach();view=previous;main.innerHTML=planningView();}else renderWithCoach();};
function planningView(){const s=selectedSession,r=currentRecord();return title('PLANEACIÓN Y EJECUCIÓN','Categoría '+s.category,WEEKDAYS[s.day]+' '+niceDate(s.date)+' · '+s.start+'–'+s.end,btn('Volver a la agenda',"go('sesiones')"))+`<div class="notice neutral">${CLUB.venues[s.venue]} · ${coachNames(s)}. La ejecución de la sesión y la práctica realizada por cada profesor se registran por separado.</div><div class="dashboard-grid"><section class="card"><div class="card-head"><h2>Planeación de la sesión</h2></div><div class="training-inner"><label class="field">Foto o PDF<input type="file" accept="image/*,application/pdf" onchange="attachPlan(this.files[0])"></label><p id="file-note" class="saved-note">${esc(r.plan||'Sin archivo seleccionado.')}</p><p class="muted" style="margin-top:10px">Archivo local de prueba: no se sube ni se conserva al recargar.</p></div></section><section class="card"><div class="card-head"><h2>Ejecución de la sesión</h2><span class="badge ${r.done?'ok':'blue'}">${r.done?'Realizada':'Programada'}</span></div><div class="training-inner"><label class="field">Observaciones<textarea id="session-notes" rows="4" placeholder="Describe lo trabajado y las novedades.">${esc(r.notes)}</textarea></label><div class="form-actions"><button class="btn primary" onclick="completeSession()">Guardar como realizada</button></div></div></section></div>`;}
attachPlan=function(file){if(!file)return;if(!(file.type.startsWith('image/')||file.type==='application/pdf'))return toast('Selecciona una imagen o PDF.');if(file.size>10*1024*1024)return toast('Máximo 10 MB.');const r=currentRecord();r.plan=file.name;planName=file.name;document.querySelector('#file-note').textContent=file.name+' · seleccionado en esta prueba';toast('Archivo seleccionado. No se envía al servidor.');};
completeSession=function(){const r=currentRecord();r.notes=document.querySelector('#session-notes').value;r.done=true;render();toast('Sesión realizada en la prueba. Confirma cada profesor por separado en Pago a entrenadores.');};
attendanceView=function(){const s=selectedSession,ps=sessionPlayers(),r=currentRecord(),marked=ps.filter(p=>r.attendance[p.id]).length;return title('ASISTENCIA POR SESIÓN','Categoría '+s.category,WEEKDAYS[s.day]+' '+niceDate(s.date)+' · '+s.start+'–'+s.end,btn('Ver planeación',"go('planeacion')",false,'file'))+`<p class="sub" style="margin-bottom:20px">${CLUB.venues[s.venue]} · ${coachNames(s)}</p>${ps.some(p=>!eligible(p))?'<div class="notice">La asistencia registrada no levanta la restricción por mensualidad ni confirma un pago.</div>':''}<section class="card"><div class="card-head"><div><h2>Lista del entrenamiento</h2><p>Una lista compartida por los profesores de esta sesión.</p></div><span class="badge blue" id="att-count">${marked} / ${ps.length}</span></div>${ps.map(p=>`<div class="attendance-row">${person(p)}${badge(p)}<select aria-label="Asistencia de ${esc(p.name)}" onchange="markAttendance(${p.id},this.value)">${[['','Sin registrar'],['presente','Presente'],['ausente','Ausente'],['excusado','Excusado'],['tarde','Llegó tarde']].map(([v,t])=>`<option value="${v}" ${r.attendance[p.id]===v?'selected':''}>${t}</option>`).join('')}</select></div>`).join('')}${ps.length?`<div class="attendance-footer"><span id="att-note">${r.saved?'Guardada en esta prueba.':'Completa los estados antes de guardar.'}</span><button class="btn primary" onclick="saveAttendance()">Guardar asistencia</button></div>`:'<div class="empty">Esta categoría ya tiene horario y entrenadores.<br>Aún no hay deportistas cargados en esta muestra.</div>'}</section>`;};
markAttendance=function(id,val){if(!sessionPlayers().some(p=>p.id===id)||!['','presente','ausente','excusado','tarde'].includes(val))throw Error('Asistencia no válida');const r=currentRecord();r.attendance[id]=val;r.saved=false;attendanceSaved=false;document.querySelector('#att-count').textContent=sessionPlayers().filter(p=>r.attendance[p.id]).length+' / '+sessionPlayers().length;document.querySelector('#att-note').textContent='Cambios sin guardar.';};
saveAttendance=function(){const ps=sessionPlayers(),r=currentRecord();if(!ps.length||ps.some(p=>!r.attendance[p.id]))return toast('Completa los estados de todos los deportistas.');r.saved=true;attendanceSaved=true;document.querySelector('#att-note').textContent='Guardada en esta prueba · '+new Date().toLocaleTimeString('es-CO',{hour:'2-digit',minute:'2-digit'});toast('Lista de esta sesión guardada en la prueba.');};
function payRows(){return occurrences(payStart,payEnd).flatMap(s=>s.coaches.map(id=>({...s,coach:coachById(id),workKey:s.key+'_'+id}))).filter(r=>payCoach==='Todos'||r.coach.id===payCoach).sort((a,b)=>a.date.localeCompare(b.date)||a.start.localeCompare(b.start)||a.coach.name.localeCompare(b.coach.name));}
function workStatus(row){return coachWork[row.workKey]?.state||'programada';}
function coachPaymentsView(){const rows=payRows(),active=rows.filter(r=>workStatus(r)!=='cancelada'),earned=rows.filter(r=>['realizada','pagada'].includes(workStatus(r))),paid=rows.filter(r=>workStatus(r)==='pagada'),sum=rs=>rs.reduce((n,r)=>n+r.coach.rate,0);return title('CONTROL DE PRÁCTICAS','Pago a entrenadores','Tarifa por profesor y por sesión de 90 minutos. Estimaciones en pesos colombianos.')+`<div class="toolbar payroll-filters"><label class="field">Desde<input type="date" value="${payStart}" id="pay-start"></label><label class="field">Hasta<input type="date" value="${payEnd}" id="pay-end"></label><label class="field">Entrenador<select id="pay-coach"><option value="Todos">Todos</option>${CLUB.coaches.map(c=>`<option value="${c.id}" ${payCoach===c.id?'selected':''}>${c.name}</option>`).join('')}</select></label><button class="btn primary" onclick="applyPayPeriod()">Consultar periodo</button></div><div class="stats">${stat('Estimado del periodo',money(sum(active)),active.length+' prácticas individuales previstas','calendar')}${stat('Realizado confirmado',money(sum(earned)),earned.length+' prácticas confirmadas en la prueba','check')}${stat('Pendiente de pago',money(sum(earned)-sum(paid)),'Solo prácticas confirmadas','clock')}${stat('Pagado en la prueba',money(sum(paid)),paid.length+' prácticas registradas como pagadas','wallet')}</div><div class="notice neutral">Las sesiones programadas son una proyección, no una deuda. Confirma la práctica de cada profesor antes de registrar su pago. Todos los cambios de esta pantalla son de prueba.</div><section class="card"><div class="card-head"><h2>Resumen por entrenador</h2><span class="badge">${niceDate(payStart)} – ${niceDate(payEnd)}</span></div><div class="table-wrap"><table><thead><tr><th>Entrenador</th><th>Prácticas previstas</th><th>Por práctica</th><th>Estimado</th><th>Pendiente confirmado</th></tr></thead><tbody>${CLUB.coaches.filter(c=>payCoach==='Todos'||c.id===payCoach).map(c=>{const rr=rows.filter(r=>r.coach.id===c.id),aa=rr.filter(r=>workStatus(r)!=='cancelada'),due=rr.filter(r=>workStatus(r)==='realizada');return `<tr><td><strong>${c.name}</strong></td><td>${aa.length}</td><td>${money(c.rate)}</td><td>${money(sum(aa))}</td><td>${money(sum(due))}</td></tr>`}).join('')}</tbody></table></div></section><section class="card"><div class="card-head"><div><h2>Prácticas individuales</h2><p>Diego tiene dos registros por día: 17:30 y 19:00.</p></div></div><div class="table-wrap"><table><thead><tr><th>Fecha y horario</th><th>Entrenador / categoría</th><th>Valor</th><th>Estado</th><th>Acción de prueba</th></tr></thead><tbody>${rows.map(r=>{const state=workStatus(r);return `<tr><td>${niceDate(r.date)}<br><small class="muted">${r.start}–${r.end}</small></td><td><b>${r.coach.name}</b><br><small class="muted">${r.category} · ${CLUB.venues[r.venue]}</small></td><td>${money(r.coach.rate)}</td><td><span class="badge ${state==='pagada'?'ok':state==='realizada'?'blue':state==='cancelada'?'danger':''}">${{programada:'Programada',realizada:'Realizada',pagada:'Pagada · prueba',cancelada:'Cancelada'}[state]}</span></td><td>${state==='programada'?`<button class="btn small" onclick="setCoachWork('${r.workKey}','realizada')">Confirmar práctica</button> <button class="btn link" onclick="setCoachWork('${r.workKey}','cancelada')">Cancelar</button>`:state==='realizada'?`<button class="btn small primary" onclick="payCoachPractice('${r.workKey}')">Registrar pago</button>`:state==='cancelada'?`<button class="btn link" onclick="setCoachWork('${r.workKey}','programada')">Restablecer</button>`:'<span class="muted">Confirmado en esta prueba</span>'}</td></tr>`}).join('')||'<tr><td colspan="5">No hay prácticas para el periodo seleccionado.</td></tr>'}</tbody></table></div></section>`;}
function applyPayPeriod(){const s=document.querySelector('#pay-start').value,e=document.querySelector('#pay-end').value,c=document.querySelector('#pay-coach').value;const days=(new Date(e+'T12:00:00Z')-new Date(s+'T12:00:00Z'))/86400000;if(!s||!e||!Number.isFinite(days)||days<0||days>365)return toast('Elige un periodo válido de hasta 366 días.');payStart=s;payEnd=e;payCoach=c;render();}
function setCoachWork(key,state){if(role!=='admin'||!['programada','realizada','cancelada'].includes(state))throw Error('Acción no permitida');const r=payRows().find(r=>r.workKey===key);if(!r||workStatus(r)==='pagada')return toast('La práctica no puede modificarse.');coachWork[key]={state};render();toast(state==='realizada'?'Práctica confirmada en la prueba; pendiente de pago.':state==='cancelada'?'Práctica cancelada; excluida del estimado.':'Práctica restablecida como programada.');}
function payCoachPractice(key){const r=payRows().find(r=>r.workKey===key);if(role!=='admin'||!r||workStatus(r)!=='realizada')return toast('Primero confirma que el profesor realizó la práctica.');showModal('Registrar pago de prueba',`<p>${r.coach.name} · ${r.category}</p><p class="sub">${niceDate(r.date)} · ${r.start}–${r.end}</p><div class="bmi-result"><span>Valor de la práctica</span><strong>${money(r.coach.rate)}</strong></div><p class="muted" style="margin-top:15px">Este botón solo actualiza la demostración. No transfiere dinero ni genera un gasto real.</p><div class="form-actions"><button class="btn" onclick="modal.close()">Volver</button><button class="btn primary" onclick="confirmCoachPayment('${key}')">Confirmar pago de prueba</button></div>`);}
function confirmCoachPayment(key){const r=payRows().find(r=>r.workKey===key);if(role!=='admin'||!r||workStatus(r)!=='realizada')return;coachWork[key]={state:'pagada'};modal.close();render();toast('Pago registrado en la prueba, sin mover dinero.');}
document.querySelector('#role').onchange=e=>{role=e.target.value;modal.close();if(role==='coach'){const s=occurrences(agendaStart,isoAdd(agendaStart,6)).find(forCoach);if(s)selectedSession=s;}go('inicio');};
render();
